CREATE TABLE payment_gateway_intents (id VARCHAR(64) PRIMARY KEY,institution_id VARCHAR(64) NOT NULL,student_id VARCHAR(64) NOT NULL,amount_minor INTEGER NOT NULL,currency VARCHAR(8) NOT NULL,provider VARCHAR(32) NOT NULL,payer_msisdn VARCHAR(32) NOT NULL,idempotency_key VARCHAR(160) NOT NULL,merchant_reference VARCHAR(120) NOT NULL,provider_reference VARCHAR(160),status VARCHAR(20) NOT NULL,created_by VARCHAR(64) NOT NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,expires_at TIMESTAMP NOT NULL,failure_code VARCHAR(100),receipt_id VARCHAR(64),CONSTRAINT uq_gateway_idempotency UNIQUE(institution_id,idempotency_key),CONSTRAINT uq_gateway_merchant_ref UNIQUE(merchant_reference),CONSTRAINT uq_gateway_provider_ref UNIQUE(provider,provider_reference));
CREATE INDEX ix_gateway_intent_institution ON payment_gateway_intents(institution_id); CREATE INDEX ix_gateway_intent_student ON payment_gateway_intents(student_id); CREATE INDEX ix_gateway_intent_provider ON payment_gateway_intents(provider); CREATE INDEX ix_gateway_intent_status ON payment_gateway_intents(status);
CREATE TABLE payment_gateway_events (id VARCHAR(64) PRIMARY KEY,provider VARCHAR(32) NOT NULL,provider_event_id VARCHAR(160) NOT NULL,payment_intent_id VARCHAR(64) NOT NULL,provider_reference VARCHAR(160),status VARCHAR(30) NOT NULL,payload_sha256 VARCHAR(64) NOT NULL,received_at TIMESTAMP NOT NULL,processed BOOLEAN NOT NULL,CONSTRAINT uq_gateway_provider_event UNIQUE(provider,provider_event_id));
CREATE INDEX ix_gateway_event_provider ON payment_gateway_events(provider); CREATE INDEX ix_gateway_event_intent ON payment_gateway_events(payment_intent_id);
